+
+namespace OpenAuth.App.Finance
+{
+    /// <summary>
+    /// 
+    /// </summary>
+    public class PenaltyCalculationService : OnlyUnitWorkBaeApp, IPenaltyCalculationService
+    {
+        private readonly IEnumerable<IPenaltyRuleProcessor> _allProcessors; //处理器，处理所有罚款事件
+        private readonly IPenaltyLedgerService _ledgerService; //记账，明细
+        /// <summary>
+        /// 
+        /// </summary>
+        /// <param name="unitWork"></param>
+        /// <param name="auth"></param>
+        /// <param name="globalIdentityApp"></param>
+        /// <param name="allProcessors"></param>
+        /// <param name="ledgerService"></param>
+        public PenaltyCalculationService(
+            IUnitWork unitWork, 
+            IAuth auth, 
+            GlobalIdentificationApp globalIdentityApp,
+            IEnumerable<IPenaltyRuleProcessor> allProcessors,
+            IPenaltyLedgerService ledgerService) : base(unitWork, auth)
+        {
+            _allProcessors = allProcessors;
+            _ledgerService = ledgerService;
+        }
+        /// <summary>
+        /// 
+        /// </summary>
+        /// <param name="jobRunId"></param>
+        /// <returns></returns>
+        public async Task BackgroundService(string jobRunId)
+        {
+            // 获取所有活跃的罚款事件
+            var allActive = await UnitWork.Find<PenaltyRuleDefinition>(r => r.IsActive).ToListAsync();
+
+            var allActiveRules = allActive
+                .GroupBy(r => r.RuleHandlerCode)
+                .ToList();
+            foreach (var group in allActiveRules)
+            {
+                await ProcessRuleGroupAsync(jobRunId, group);
+            }
+        }
+
+        /// <summary>
+        /// 处理规则分组
+        /// </summary>
+        private async Task ProcessRuleGroupAsync(string jobRunId, IGrouping<string, PenaltyRuleDefinition> group)
+        {
+            var processor = _allProcessors.FirstOrDefault(p => p.HandlerCode == group.Key);
+            if (processor == null) return;
+
+            var (newEvents, resolvedEvents, canceledEvents) = await processor.ProcessAsync(group.ToList());
+
+            await ProcessNewEventsAsync(newEvents);
+            await ProcessResolvedAndCanceledEventsAsync(resolvedEvents, canceledEvents);
+            await UpdateJobAuditAsync(group.Key);
+            await UnitWork.SaveAsync();
+
+            // 记账
+            await _ledgerService.ProcessDailyCalculations(jobRunId, group.FirstOrDefault().Id);
+            // 计算并更新每个罚款事件的总罚款金额
+            await UpdateTotalPenaltyAmounts(group.FirstOrDefault().Id);
+        }
+
+        /// <summary>
+        /// 处理新立案事件
+        /// </summary>
+        private async Task ProcessNewEventsAsync(List<Dto.PenaltyEventData> newEvents)
+        {
+            var addDbEvent = new List<PenaltyEvent>();
+            foreach (var eventData in newEvents)
+            {
+                var isAlreadyActive = await CheckEventAlreadyActiveAsync(eventData);
+                if (!isAlreadyActive)
+                {
+                    var dbEvent = CreatePenaltyEventFromData(eventData);
+                    addDbEvent.Add(dbEvent);
+                }
+            }
+
+            if (addDbEvent.Any())
+            {
+                await UnitWork.BatchAddAsync<PenaltyEvent, int>(addDbEvent.ToArray());
+            }
+        }
+
