+
+            if (resolvedEvents.Any())
+            {
+                var resolvedList = await ProcessResolvedEventsAsync(resolvedEvents);
+                updatePenaltyEventList.AddRange(resolvedList);
+            }
+
+            if (canceledEvents.Any())
+            {
+                var canceledList = await ProcessCanceledEventsAsync(canceledEvents);
+                updatePenaltyEventList.AddRange(canceledList);
+            }
+
+            if (updatePenaltyEventList.Any())
+            {
+                await UnitWork.BatchUpdateAsync<PenaltyEvent>(updatePenaltyEventList.ToArray());
+            }
+        }
+
