+            if (audit == null)
+            {
+                var addAudit = new PenaltyJobAudit
+                {
+                    HandlerCode = handlerCode,
+                    LastProcessedTimestamp = DateTime.Now
+                };
+                await UnitWork.AddAsync<PenaltyJobAudit, int>(addAudit);
+            }
+            else
+            {
+                audit.LastProcessedTimestamp = DateTime.Now;
+                await UnitWork.UpdateAsync<PenaltyJobAudit>(audit);
+            }
+        }
+
+        /// <summary>
+        /// 计算并更新所有活跃罚款事件的总罚款金额
+        /// </summary>
+        /// <param name="runId"></param>
+        /// <returns></returns>
+        public async Task UpdateTotalPenaltyAmounts(int runId)
+        {
+            try
+            {
+                LogHelper.Info("开始计算并更新所有活跃罚款事件的总罚款金额", nameof(PenaltyCalculationService), nameof(UpdateTotalPenaltyAmounts));
+                
+                // 获取需要更新的事件ID列表
+                var eventIds = await UnitWork.Find<PenaltyEvent>(e => e.RuleDefinitionId == runId)
+                    .Select(e => e.Id)
+                    .ToListAsync();
+
+                if (!eventIds.Any())
+                {
+                    LogHelper.Info("没有需要更新的罚款事件", nameof(PenaltyCalculationService), nameof(UpdateTotalPenaltyAmounts));
+                    return;
+                }
+
+                // 分批处理，每批100条
+                const int batchSize = 1000;
+                int totalUpdated = 0;
+                
+                for (int i = 0; i < eventIds.Count; i += batchSize)
+                {
+                    var batchIds = eventIds.Skip(i).Take(batchSize).ToList();
+                    var idsParam = string.Join(",", batchIds);
+                    
+                    // 使用JOIN优化的批量更新SQL，避免子查询
+                    string sql = $@"
+                    UPDATE penalty_events pe
+                    INNER JOIN (
+                        SELECT EventId, SUM(Amount) as TotalAmount
+                        FROM penalty_ledger
+                        WHERE EventId IN ({idsParam})
+                        GROUP BY EventId
+                    ) pl ON pe.Id = pl.EventId
+                    SET pe.TotalPenaltyAmount = COALESCE(pl.TotalAmount, 0)
+                    WHERE pe.Id IN ({idsParam})";
+
+                    var resultCount = await UnitWork.ExecuteSqlAsync<Nsap4SettlementContext>(sql);
+
+                    totalUpdated += resultCount;
+                    
+                    LogHelper.Info($"批次 {i / batchSize + 1} 更新了 {resultCount} 条记录", nameof(PenaltyCalculationService), nameof(UpdateTotalPenaltyAmounts));
+                }
+
+                LogHelper.Info($"计算并更新所有活跃罚款事件的总罚款金额成功，共更新 {totalUpdated} 条记录", nameof(PenaltyCalculationService), nameof(UpdateTotalPenaltyAmounts));
+            }
+            catch (Exception ex)
+            {
+                LogHelper.Error(ex, "计算并更新所有活跃罚款事件的总罚款金额失败", nameof(PenaltyCalculationService), nameof(UpdateTotalPenaltyAmounts));
+            }
+        }
+    }
+}

